// doc: bin(x).count('1') returns the number of set bits in the binary representation
//      of a non-negative integer x. For negative integers Python uses a sign-magnitude
//      representation conceptually, but in practice bin() prefixes '-' and counts bits
//      of the absolute value, so we restrict to non-negative inputs here.
function BinCountOnes(x: int): int
  requires x >= 0
{
  if x == 0 then 0
  else (x % 2) + BinCountOnes(x / 2)
}

// doc: Python's sorted() with a key function sorts stably in ascending order of the
//      key values. When used to sort integers by (popcount, value), ties in popcount
//      are broken by the integer value itself.
//      We model the sentinel for negative infinity as -(2^62) to avoid the Dafny
//      limitation that << requires bitvector operands.
const NEG_INF_SENTINEL: int := -(4611686018427387904)  // -(2^62)

// doc: The sort key used in the Python program maps a non-negative integer x to
//      (popcount(x), x), and maps a negative integer (used as a sentinel for -infinity)
//      to (popcount of its absolute value, NEG_INF_SENTINEL) so it sorts before
//      non-negative values with the same popcount.
function SortKey(x: int): (int, int)
{
  var kx := (BinCountOnes(if x >= 0 then x else -x), if x >= 0 then x else NEG_INF_SENTINEL);
  kx
}

// doc: Tuple comparison in Python is lexicographic: (a, b) < (c, d) iff a < c, or
//      a == c and b < d.
predicate TupleLt(a: (int, int), b: (int, int))
{
  a.0 < b.0 || (a.0 == b.0 && a.1 < b.1)
}

