  // synth: result elements remain non-negative (preserved from input)
  ensures forall i :: 0 <= i < |result| ==> result[i] >= 0
  // synth: result is non-decreasing in SortKey order
  ensures forall i :: 0 <= i < |result| - 1 ==> !TupleLt(SortKey(result[i + 1]), SortKey(result[i]))

