theory:
// synth: library theory (phase 0)
// doc: Lexicographic comparison of 2-tuples of integers, matching Python's tuple
// comparison: (a1, b1) <= (a2, b2) iff a1 < a2, or (a1 == a2 and b1 <= b2).
function Tuple2Le(t1: (int, int), t2: (int, int)): bool {
  t1.0 < t2.0 || (t1.0 == t2.0 && t1.1 <= t2.1)
}

// doc: Tuple2Le is reflexive: every 2-tuple compares less-than-or-equal to itself.
lemma Tuple2LeRefl(t: (int, int))
  ensures Tuple2Le(t, t)
{}

// doc: Tuple2Le is transitive.
lemma Tuple2LeTrans(a: (int, int), b: (int, int), c: (int, int))
  requires Tuple2Le(a, b)
  requires Tuple2Le(b, c)
  ensures  Tuple2Le(a, c)
{}

// doc: Python's sorted(xs, key=key) returns a new list whose elements are a
// permutation of xs, ordered so that key(xs[i]) <= key(xs[j]) (lexicographically)
// whenever i <= j in the result. The sort is stable. The original sequence xs is
// not modified. The key function is called exactly once per element.
function {:axiom} SortedByKey<T>(xs: seq<T>, key: T -> (int, int)): seq<T>

// doc: The result of SortedByKey is a permutation of the input (same multiset).
// axiom-justification: Encodes Python's guarantee that sorted() returns all
// original elements; cannot be derived without a constructive sort definition.
lemma {:axiom} SortedByKeyPermutation<T>(xs: seq<T>, key: T -> (int, int))
  ensures multiset(SortedByKey(xs, key)) == multiset(xs)

// doc: The result of SortedByKey is non-decreasingly ordered by the key function
// under lexicographic tuple comparison: for all i <= j in the result,
// Tuple2Le(key(result[i]), key(result[j])) holds.
// axiom-justification: Encodes Python's guarantee that sorted() produces an
// ordered sequence; cannot be derived without a constructive sort definition.
lemma {:axiom} SortedByKeyOrdered<T>(xs: seq<T>, key: T -> (int, int))
  ensures forall i, j :: 0 <= i <= j < |SortedByKey(xs, key)| ==>
    Tuple2Le(key(SortedByKey(xs, key)[i]), key(SortedByKey(xs, key)[j]))

// doc: Python's len(s) returns the number of items in a sequence. For a string,
// this is the number of Unicode code points. Raises no exception for any
// sequence or string (including empty ones).
function Len<T>(s: seq<T>): int {
  |s|
}

// doc: Python integer floor division x // y truncates toward negative infinity.
// Raises ZeroDivisionError if y == 0. For positive divisor y > 0:
// result == floor(x / y), which equals (x - (x % y)) / y.
// axiom-justification: Dafny's built-in `/` truncates toward zero, not toward
// negative infinity; this axiom captures the divergence for negative dividends.
function {:axiom} FloorDiv(x: int, y: int): int
  requires y != 0

// doc: Python integer modulo x % y has the same sign as y (not x).
// Raises ZeroDivisionError if y == 0.
// axiom-justification: Dafny's built-in `%` has the same sign as x; this axiom
// captures Python's sign convention which differs for negative x with positive y.
function {:axiom} PyMod(x: int, y: int): int
  requires y != 0
  ensures 0 <= PyMod(x, y) < y || y < PyMod(x, y) <= 0

