// doc: str.join(iterable) concatenates the strings in `parts` with `sep` between
// each pair. Returns "" if parts is empty, parts[0] if parts has one element,
// and otherwise the concatenation of all parts separated by sep.
// axiom-justification: StringJoin is an opaque function over string sequences;
// the base cases and length-preserving sort are documented Python behaviours
// that cannot be derived from first principles in Dafny.
function {:axiom} StringJoin(sep: string, parts: seq<string>): string
  ensures parts == [] ==> StringJoin(sep, parts) == ""
  ensures |parts| == 1 ==> StringJoin(sep, parts) == parts[0]

// doc: sorted(xs) returns a new list with the elements of xs in non-decreasing
// order. The returned sequence has the same length as xs and contains exactly
// the same elements (as a multiset). Python's sorted never raises on a list of
// ints and is stable, but stability is not captured here.
// axiom-justification: Sorting is an external operation; Dafny cannot derive
// the multiset-equality or ordering properties without a body or axiom.
function {:axiom} SortedInts(xs: seq<int>): seq<int>
  ensures |SortedInts(xs)| == |xs|
  ensures forall i, j :: 0 <= i < j < |SortedInts(xs)| ==>
            SortedInts(xs)[i] <= SortedInts(xs)[j]
  ensures multiset(SortedInts(xs)) == multiset(xs)

