// synth: termination measure on length of xs
  decreases |xs|
{
  // synth: base case - empty sequence
  if |xs| == 0 then []
  // synth: recursive case - dict lookup and recurse
  else [m[xs[0]]] + ApplyDictToSeq(m, xs[1..])
