// synth: library theory (phase 0)
// doc: Returns the index of the first occurrence of x in s.
// Requires x to be present in s; if x is not in s, the behaviour is undefined.
// The returned index i satisfies s[i] == x and for all k < i, s[k] != x.
function {:axiom} SeqFirstIndex<T(==)>(s: seq<T>, x: T): nat
  requires x in s
  ensures SeqFirstIndex(s, x) < |s|
  ensures s[SeqFirstIndex(s, x)] == x
  ensures forall k: nat :: k < SeqFirstIndex(s, x) ==> s[k] != x

// doc: Returns a stable sort of sequence s using the provided key function.
// The result is a permutation of s (same multiset), the same length as s,
// elements are ordered non-decreasingly by key, and equal-key elements
// preserve their original relative order (stability).
// K must support a total order via the <= operator.
function {:axiom} StableSortByKey<T, K>(s: seq<T>, key: T -> K): seq<T>
  ensures |StableSortByKey(s, key)| == |s|
  ensures multiset(StableSortByKey(s, key)) == multiset(s)

// doc: Predicate: sequence s has a duplicate element, i.e. there exist two
// distinct indices with equal values.
predicate HasDuplicate<T(==)>(s: seq<T>) {
  (exists oi, oj :: (0 <= oi < oj < |s| &&
    s[oi] == s[oj]))
}

