// synth: library theory (phase 0)
// doc: Python's `//` operator on integers performs floor division: for any
// integers a and b (b != 0), a // b == floor(a / b). For negative dividends
// or divisors this rounds toward negative infinity, not toward zero.
// Raises ZeroDivisionError if b == 0.
function FloorDiv(a: int, b: int): int
  requires b != 0
{
  if (a >= 0 && b > 0) || (a <= 0 && b < 0) then a / b
  else if a % b == 0 then a / b
  else a / b - 1
}

// doc: Python's `%` operator on integers returns the remainder consistent with
// floor division: a % b == a - b * (a // b). The result always has the same
// sign as b (or is zero). Raises ZeroDivisionError if b == 0.
function Mod(a: int, b: int): int
  requires b != 0
{
  a - b * FloorDiv(a, b)
}

