// synth: library theory (phase 0)
// doc: Python list slicing l[start::step] returns a new list of elements
// at indices start, start+step, start+2*step, ... as long as the index is
// less than len(l). When start >= len(l) the result is []. step must be
// a positive integer; step=0 raises ValueError (not modelled here).
// l[::2] means start=0, step=2; result length is (len(l)+1)/2.
// l[1::2] means start=1, step=2; result length is len(l)/2.
function StepSlice<T>(l: seq<T>, start: nat, step: nat): seq<T>
  requires step >= 1
  decreases if start < |l| then |l| - start else 0
{
  if start >= |l| then []
  else [l[start]] + StepSlice(l, start + step, step)
}

// doc: Python's sorted(iterable) returns a new list containing all elements
// of iterable in non-decreasing order. The sort is stable: elements that
// compare equal appear in the same relative order as in the input.
// Raises TypeError if the elements are not mutually comparable.
// For a list of length n the result also has length n.
function Sorted<T>(l: seq<T>): seq<T>

// doc: Python's zip(a, b) returns an iterator of 2-tuples where the i-th
// tuple is (a[i], b[i]). Iteration stops when the shorter iterable is
// exhausted, so the result length is min(len(a), len(b)).
// An empty result is produced when either argument is empty.
function Zip<A, B>(a: seq<A>, b: seq<B>): seq<(A, B)>
{
  if |a| == 0 || |b| == 0 then []
  else [(a[0], b[0])] + Zip(a[1..], b[1..])
}

// doc: The list comprehension [i for pair in zip(a, b) for i in pair]
// interleaves the two sequences element by element, producing
// [a[0], b[0], a[1], b[1], ...]. The result has length 2*min(|a|,|b|).
// This models flattening a sequence of pairs into a flat sequence.
function FlattenPairs<T>(pairs: seq<(T, T)>): seq<T>
{
  if |pairs| == 0 then []
  else [pairs[0].0, pairs[0].1] + FlattenPairs(pairs[1..])
}

